import{_ as t,c as o,o as n,ae as i}from"./chunks/framework.CBTkueSR.js";const d=JSON.parse('{"title":"卷八 标准与语言篇 | 统一支付术语与行业规范","description":"","frontmatter":{},"headers":[],"relativePath":"volume8.md","filePath":"volume8.md"}'),l={name:"volume8.md"};function a(e,r,s,g,u,c){return n(),o("div",null,[...r[0]||(r[0]=[i('<h1 id="卷八-标准与语言篇-统一支付术语与行业规范" tabindex="-1">卷八 标准与语言篇 | 统一支付术语与行业规范 <a class="header-anchor" href="#卷八-标准与语言篇-统一支付术语与行业规范" aria-label="Permalink to &quot;卷八 标准与语言篇 | 统一支付术语与行业规范&quot;">​</a></h1><p>本篇旨在梳理和定义支付行业的核心术语，为从业者、监管机构和合作伙伴提供一个共同的语言基础，促进有效沟通与精准协作。</p><h2 id="【1】-支付基础概念" tabindex="-1">【1】 支付基础概念 <a class="header-anchor" href="#【1】-支付基础概念" aria-label="Permalink to &quot;【1】 支付基础概念&quot;">​</a></h2><ul><li><strong>支付 (Payment)</strong>：指单位、个人之间因商品交易、劳务提供、资金划转等产生的货币给付行为。广义上包括货币的物理转移和账面价值的转移。</li><li><strong>清算 (Clearing)</strong>：指在一定区域内，对支付指令进行交换、计算，以确定各参与机构应收或应付金额的过程。清算是“算账”。</li><li><strong>结算 (Settlement)</strong>：指根据清算结果，在中央银行或指定清算机构的账簿上，对各参与机构的资金账户进行借记或贷记，以最终完成资金划转的过程。结算是“结账”。</li><li><strong>四方模式 (Four-Party Model)</strong>：由卡组织（如银联、Visa）建立的，包含发卡行、收单行、商户、持卡人四个主要参与方的支付模式。卡组织在其中扮演网络转接和清算组织者的角色。</li><li><strong>三方模式 (Three-Party Model)</strong>：由支付机构（如支付宝、PayPal）建立的，包含支付机构、付款人、收款人三个主要参与方的支付模式。交易在支付机构的账户体系内闭环完成。</li></ul><h2 id="【2】-机构分类与监管术语" tabindex="-1">【2】 机构分类与监管术语 <a class="header-anchor" href="#【2】-机构分类与监管术语" aria-label="Permalink to &quot;【2】 机构分类与监管术语&quot;">​</a></h2><ul><li><strong>中央银行 (Central Bank)</strong>：国家的金融中枢，负责制定和执行货币政策、维护金融稳定、提供最终清算服务。在我国指中国人民银行（PBOC）。</li><li><strong>清算机构 (Clearing House)</strong>：经中央银行批准，专门从事支付清算业务的组织。在我国，银行卡清算机构为中国银联（UnionPay），网络支付清算机构为网联清算有限公司（NUCC）。</li><li><strong>非银行支付机构 (Non-bank Payment Institution)</strong>：俗称“第三方支付公司”，指获得《支付业务许可证》，在收付款人之间作为中介机构提供网络支付、银行卡收单、预付卡发行与受理等服务的非银行机构。</li><li><strong>备付金 (Provisions)</strong>：支付机构为办理客户委托的支付业务而实际收到的预收待付货币资金。根据监管要求，备付金需100%集中存管于中央银行或符合规定的商业银行。</li></ul><h2 id="【3】-交易模式名词-a-b-c-g-端-、b2b-b2c-p2p-等" tabindex="-1">【3】 交易模式名词 (A/B/C/G 端 、B2B/B2C/P2P 等) <a class="header-anchor" href="#【3】-交易模式名词-a-b-c-g-端-、b2b-b2c-p2p-等" aria-label="Permalink to &quot;【3】 交易模式名词 (A/B/C/G 端 、B2B/B2C/P2P 等)&quot;">​</a></h2><ul><li><strong>C端 (Consumer)</strong>：指个人消费者或终端用户。</li><li><strong>B端 (Business)</strong>：指企业或商户。</li><li><strong>G端 (Government)</strong>：指政府机构或公共事业单位。</li><li><strong>A端 (Agent/Agency)</strong>：指代理商或渠道合作伙伴。</li><li><strong>B2C (Business-to-Consumer)</strong>：企业对个人的交易模式，如在线零售。</li><li><strong>B2B (Business-to-Business)</strong>：企业对企业的交易模式，如企业采购、供应链付款。</li><li><strong>P2P (Peer-to-Peer/Person-to-Person)</strong>：个人对个人的交易模式，如个人转账。</li></ul><h2 id="【4】-资金与货币层级术语-m0-m3" tabindex="-1">【4】 资金与货币层级术语 (M0-M3) <a class="header-anchor" href="#【4】-资金与货币层级术语-m0-m3" aria-label="Permalink to &quot;【4】 资金与货币层级术语 (M0-M3)&quot;">​</a></h2><ul><li><strong>M0 (货币)</strong>：流通中的现金，即中央银行发行的纸币和硬币。</li><li><strong>M1 (狭义货币)</strong>：M0 + 企业活期存款。M1反映了经济中的现实购买力。</li><li><strong>M2 (广义货币)</strong>：M1 + 准货币（居民储蓄存款、单位定期存款、其他存款等）。M2不仅反映现实购买力，还反映潜在购买力。</li><li><strong>M3</strong>：在部分国家，M3是在M2基础上增加了一些流动性较弱的资产，如金融债券、商业票据等。中国目前未正式测算M3。</li></ul><h2 id="【5】-技术与系统术语-网关、接口、密钥等" tabindex="-1">【5】 技术与系统术语(网关、接口、密钥等) <a class="header-anchor" href="#【5】-技术与系统术语-网关、接口、密钥等" aria-label="Permalink to &quot;【5】 技术与系统术语(网关、接口、密钥等)&quot;">​</a></h2><ul><li><strong>支付网关 (Payment Gateway)</strong>：连接商户网站/App与银行或支付处理网络的接口，负责交易信息的传递、格式转换和安全验证。</li><li><strong>API (Application Programming Interface)</strong>：应用程序编程接口，是支付机构提供给商户或开发者，用于集成其支付能力的一套预定义的函数、协议和工具。</li><li><strong>SDK (Software Development Kit)</strong>：软件开发工具包，是支付机构为方便开发者使用其API而提供的代码库、示例和文档的集合。</li><li><strong>密钥 (Key)</strong>：在密码学中，用于加密和解密数据的一段参数。分为对称密钥（加解密使用同一密钥）和非对称密钥（公钥加密，私钥解密）。</li><li><strong>硬件加密机 (HSM, Hardware Security Module)</strong>：一种专用的、防篡改的硬件设备，用于保护和管理密钥的全生命周期，并执行加密运算。</li></ul><h2 id="【6】-风控与合规名词-kyc、aml-等" tabindex="-1">【6】 风控与合规名词 (KYC、AML 等) <a class="header-anchor" href="#【6】-风控与合规名词-kyc、aml-等" aria-label="Permalink to &quot;【6】 风控与合规名词 (KYC、AML 等)&quot;">​</a></h2><ul><li><strong>KYC (Know Your Customer)</strong>：了解你的客户。指金融机构为防范金融犯罪，必须执行的客户身份识别程序，包括收集、核验和记录客户的身份信息。</li><li><strong>AML (Anti-Money Laundering)</strong>：反洗钱。指为预防和打击通过金融系统掩饰、隐瞒非法资金来源和性质的活动而采取的一系列法律和监管措施。</li><li><strong>CFT (Combating the Financing of Terrorism)</strong>：反恐怖融资。</li><li><strong>风险画像 (Risk Profile)</strong>：通过分析用户的身份、行为、交易、设备等多维度信息，对其风险等级进行量化评估，形成一个多维度的风险标签集合。</li></ul><h2 id="【7】-成本与结算术语-费率、分润、周期" tabindex="-1">【7】 成本与结算术语(费率、分润、周期) <a class="header-anchor" href="#【7】-成本与结算术语-费率、分润、周期" aria-label="Permalink to &quot;【7】 成本与结算术语(费率、分润、周期)&quot;">​</a></h2><ul><li><strong>费率 (Rate)</strong>：支付机构向商户收取的支付服务费用，通常按交易金额的一定百分比计算。</li><li><strong>分润 (Profit Sharing)</strong>：在支付产业链中，收单机构、清算组织、发卡行等参与方之间，按照约定规则对商户支付的手续费进行分配的过程。</li><li><strong>T+N/D+N 结算周期</strong>： <ul><li><strong>T (Trade Date)</strong>：交易日。</li><li><strong>D (Day)</strong>：自然日。</li><li><strong>N</strong>：数字。T+N指交易日后的第N个工作日进行结算；D+N指交易日后的第N个自然日进行结算。例如，T+1是目前最常见的结算周期。</li></ul></li></ul><h2 id="【8】-国际与跨境术语-swift、cips、cbdc-等" tabindex="-1">【8】 国际与跨境术语 (SWIFT、CIPS、CBDC 等) <a class="header-anchor" href="#【8】-国际与跨境术语-swift、cips、cbdc-等" aria-label="Permalink to &quot;【8】 国际与跨境术语 (SWIFT、CIPS、CBDC 等)&quot;">​</a></h2><ul><li><strong>SWIFT (Society for Worldwide Interbank Financial Telecommunication)</strong>：环球银行金融电信协会。提供全球金融报文网络，是传统跨境支付的核心基础设施。</li><li><strong>CIPS (Cross-border Interbank Payment System)</strong>：人民币跨境支付系统。中国建设的用于人民币跨境清算的“高速公路”。</li><li><strong>CBDC (Central Bank Digital Currency)</strong>：中央银行数字货币。由中央银行发行的、具有法偿地位的数字化形态的法定货币。中国的CBDC项目为数字人民币（e-CNY）。</li><li><strong>代理行 (Correspondent Bank)</strong>：一家银行在另一家银行（通常在境外）开立账户，以便为客户提供跨境支付等金融服务。</li></ul><h2 id="【9】-新兴科技名词-ai风控、regtech、-区块链" tabindex="-1">【9】 新兴科技名词 (AI风控、RegTech、 区块链) <a class="header-anchor" href="#【9】-新兴科技名词-ai风控、regtech、-区块链" aria-label="Permalink to &quot;【9】 新兴科技名词 (AI风控、RegTech、 区块链)&quot;">​</a></h2><ul><li><strong>AI风控 (AI-powered Risk Control)</strong>：利用人工智能和机器学习技术，对海量数据进行实时分析，以更精准地识别和预测支付欺诈、信用违约等风险。</li><li><strong>RegTech (Regulatory Technology)</strong>：监管科技。指利用技术手段（特别是AI、大数据）来更高效、更低成本地满足监管合规要求的解决方案，如自动化的合规报告、智能化的反洗钱监控等。</li><li><strong>区块链 (Blockchain)</strong>：一种去中心化、不可篡改、可追溯的分布式账本技术。在支付领域，被探索用于改善跨境支付效率、供应链金融和数字资产交易。</li><li><strong>开放银行 (Open Banking)</strong>：一种通过API将银行的数据和功能安全地开放给第三方开发者的模式，旨在促进金融创新和生态合作。</li></ul>',20)])])}const m=t(l,[["render",a]]);export{d as __pageData,m as default};
